/* ZAJEDNIČKI STILOVI I UGRAĐENI FONTOVI */
@font-face {
  font-family:LumiereSerif;
  src:url('data:font/woff;base64,') format('woff');
  font-weight:400;
  font-style:normal;
  font-display:swap
}

@font-face {
  font-family:LumiereSerif;
  src:url('data:font/woff;base64,') format('woff');
  font-weight:400;
  font-style:italic;
  font-display:swap
}

@font-face {
  font-family:LumiereScript;
  src:url('data:font/woff;base64,') format('woff');
  font-weight:400;
  font-display:swap
}

@font-face {
  font-family:LumiereSans;
  src:url('data:font/woff;base64,') format('woff');
  font-weight:400;
  font-display:swap
}

.lmv {
  --lmv-paper:#ffffff;
  --lmv-ink:#171717;
  --lmv-muted:#636363;
  --lmv-accent:#76172d;
  --lmv-line:rgba(0,0,0,.18);
  --lmv-serif:LumiereSerif,Georgia,serif;
  --lmv-sans:LumiereSans,Arial,sans-serif;
  --lmv-script:LumiereScript,cursive;
  position:relative;
  isolation:isolate;
  box-sizing:border-box;
  background:var(--lmv-paper);
  color:var(--lmv-ink);
  font:400 14px/1.7 var(--lmv-sans);
  text-align:left;
  color-scheme:light;
  overflow-x:clip;
  -webkit-text-size-adjust:100%;
  -webkit-tap-highlight-color:transparent
}

.lmv[data-script="cyrillic"] {
  --lmv-script:LumiereSerif,Georgia,serif
}

:where(.lmv) *,:where(.lmv) *::before,:where(.lmv) *::after {
  box-sizing:border-box
}

:where(.lmv) h1,:where(.lmv) h2,:where(.lmv) h3,:where(.lmv) h4,:where(.lmv) p,:where(.lmv) figure {
  margin:0;
  padding:0
}

:where(.lmv) button,:where(.lmv) input,:where(.lmv) textarea,:where(.lmv) select {
  font:inherit;
  color:inherit;
  letter-spacing:normal;
  text-transform:none
}

:where(.lmv) button {
  appearance:none;
  cursor:pointer;
  touch-action:manipulation;
  border-radius:0
}

:where(.lmv) button:disabled {
  cursor:default
}

:where(.lmv) a {
  color:inherit;
  text-decoration:none
}

:where(.lmv) a:focus-visible,:where(.lmv) button:focus-visible,:where(.lmv) input:focus-visible {
  outline:2px solid var(--lmv-accent);
  outline-offset:5px
}

:where(.lmv) img {
  max-width:100%;
  display:block
}

:where(.lmv) .lmv-icon {
  display:inline-block;
  flex-shrink:0;
  object-fit:contain;
  vertical-align:middle
}

:where(.lmv) .lmv-wrap {
  width:100%;
  max-width:520px;
  margin-inline:auto;
  padding:0 30px
}

:where(.lmv) .lmv-kicker {
  font:500 10px/1.7 var(--lmv-sans);
  letter-spacing:.2em;
  text-transform:uppercase
}

:where(.lmv) .lmv-heading {
  font:400 clamp(42px,11vw,66px)/1.05 var(--lmv-serif);
  letter-spacing:-.035em;
  overflow-wrap:anywhere;
  text-wrap:balance
}

:where(.lmv) .lmv-script {
  font:400 clamp(46px,12vw,74px)/1.05 var(--lmv-script);
  letter-spacing:0
}

:where(.lmv)[data-script="cyrillic"] .lmv-script {
  font-style:italic;
  font-size:clamp(36px,9vw,57px)
}

:where(.lmv) .lmv-body {
  font-size:13px;
  line-height:1.95;
  color:var(--lmv-muted);
  white-space:pre-line;
  text-wrap:pretty;
  overflow-wrap:anywhere
}

:where(.lmv) .lmv-button {
  min-height:52px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:18px;
  border:1px solid var(--lmv-line);
  background:transparent;
  padding:14px 24px;
  font-size:11px;
  letter-spacing:.075em;
  transition:background .25s,color .25s,transform .25s;
  width:auto;
  max-width:100%;
  text-align:center
}

:where(.lmv) .lmv-button:hover {
  background:var(--lmv-ink);
  color:var(--lmv-paper)
}

:where(.lmv) .lmv-button--solid {
  background:var(--lmv-ink);
  color:var(--lmv-paper);
  border-color:var(--lmv-ink)
}

:where(.lmv) .lmv-button--solid:hover {
  background:#333333
}

:where(.lmv) .lmv-button .lmv-arrow {
  font:400 22px/1 var(--lmv-serif);
  transition:transform .25s
}

:where(.lmv) .lmv-button:hover .lmv-arrow {
  transform:translateX(4px)
}

:where(.lmv) .lmv-reveal {
  opacity:0;
  transform:translate3d(0,24px,0);
  transition:opacity .9s cubic-bezier(.22,1,.36,1) var(--lmv-delay,0ms),transform .9s cubic-bezier(.22,1,.36,1) var(--lmv-delay,0ms)
}

:where(.lmv) .lmv-reveal.is-visible {
  opacity:1;
  transform:translate3d(0,0,0)
}

:where(.lmv) .lmv-photo {
  position:relative;
  overflow:hidden;
  background:#d6d6d6;
  isolation:isolate
}

:where(.lmv) .lmv-photo>img {
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  max-width:none;
  object-fit:cover;
  object-position:var(--lmv-photo-position,50% 50%);
  filter:grayscale(1);
  transform:translate3d(0,var(--lmv-photo-shift,0px),0) scale(1.09)
}

:where(.lmv) .lmv-photo-fallback {
  position:absolute;
  inset:0;
  display:grid;
  place-items:center;
  background:linear-gradient(130deg,#dadada,#ffffff)
}

:where(.lmv) .lmv-rule {
  display:block;
  height:1px;
  background:var(--lmv-line);
  width:45px;
  margin:28px auto
}

:where(.lmv) .lmv-sr-only {
  position:absolute;
  width:1px;
  height:1px;
  margin:-1px;
  padding:0;
  overflow:hidden;
  clip:rect(0,0,0,0);
  white-space:nowrap;
  border:0
}

@media(max-width:350px) {
  :where(.lmv) .lmv-wrap {
    padding-inline:23px
  }
  :where(.lmv) .lmv-kicker {
    font-size:9px;
    letter-spacing:.15em
  }
  :where(.lmv) .lmv-body {
    font-size:12px
  }
}

@media(prefers-reduced-motion:reduce) {
  :where(.lmv) *, :where(.lmv) *::before,:where(.lmv) *::after {
    animation:none!important;
    transition:none!important;
    scroll-behavior:auto!important
  }
  :where(.lmv) .lmv-reveal {
    opacity:1;
    transform:none
  }
  :where(.lmv) .lmv-photo>img {
    transform:none!important
  }
}

/* INTRO */
.lmv.lmv-intro {
  --lmv-emblem-size:clamp(210px,66vw,300px);
  width:100%;
  max-width:680px;
  margin:auto;
  min-height:100svh;
  background:#171717;
  color:#ffffff;
  overflow:hidden
}

.lmv .lmv-intro-behind {
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  flex-direction:column;
  gap:18px;
  text-align:center;
  padding:30px;
  background:#171717;
  color:#ffffff
}

.lmv .lmv-intro-behind .lmv-script {
  font-size:75px
}

.lmv .lmv-cover {
  position:relative;
  min-height:100svh;
  background:#171717;
  isolation:isolate;
  transition:opacity .95s .15s;
  overflow:hidden
}

.lmv .lmv-cover::after {
  content:"";
  position:absolute;
  z-index:3;
  inset:10px;
  border:1px solid #ffffff55;
  pointer-events:none
}

.lmv .lmv-cover-portrait {
  position:absolute;
  inset:0;
  z-index:-1;
  background:linear-gradient(135deg,#5c5c5c,#171717);
  overflow:hidden
}

.lmv .lmv-cover-portrait img {
  height:100%;
  width:100%;
  max-width:none;
  object-fit:cover;
  object-position:var(--lmv-hero-position,50% 45%);
  filter:grayscale(1);
  transform:scale(1.04);
  animation:lmv-cinema-breathe 16s ease-in-out 2 alternate;
  transition:transform 1.2s cubic-bezier(.76,0,.24,1)
}

.lmv .lmv-cover-portrait::after {
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(180deg,#00000035 0%,#00000024 19%,#00000055 50%,#000000ad 77%,#000000c7 100%),radial-gradient(ellipse at 50% 49%,#00000038 0%,transparent 64%);
  pointer-events:none
}

.lmv .lmv-intro-stage {
  position:relative;
  min-height:100svh
}

.lmv .lmv-cover-aside {
  position:absolute;
  top:calc(50% - var(--lmv-emblem-size) * .6765 - 36px);
  left:28px;
  right:28px;
  text-align:center;
  color:#ffffffd9;
  font-size:9px;
  letter-spacing:.2em;
  text-transform:uppercase;
  line-height:1.8;
  animation:lmv-cinema-rise 1.4s .35s both
}

.lmv .lmv-intro-emblem {
  position:absolute;
  top:50%;
  left:50%;
  width:var(--lmv-emblem-size);
  aspect-ratio:340/460;
  transform:translate(-50%,-50%);
  display:grid;
  place-items:center;
  isolation:isolate;
  transition:scale 1.1s cubic-bezier(.76,0,.24,1),opacity .7s
}

.lmv .lmv-intro-emblem::before {
  content:"";
  position:absolute;
  inset:18% 18%;
  border-radius:50%;
  background:radial-gradient(ellipse,#00000022,transparent 72%);
  z-index:-1
}

.lmv .lmv-intro-emblem-frame {
  position:absolute;
  inset:0;
  display:block!important;
  width:100%;
  height:100%;
  max-width:none;
  filter:drop-shadow(0 1px 4px #00000035);
  animation:lmv-emblem-ink 1.8s .1s cubic-bezier(.22,1,.36,1) both
}

.lmv .lmv-intro-monogram {
  position:absolute;
  inset:auto;
  top:50%;
  left:50%;
  display:flex;
  align-items:baseline;
  justify-content:center;
  width:max-content;
  transform:translate(-50%,-50%);
  font:400 calc(var(--lmv-emblem-size) * .55)/1 var(--lmv-serif);
  letter-spacing:0;
  white-space:nowrap;
  text-shadow:0 2px 15px #00000025
}

.lmv .lmv-intro-initial {
  position:relative;
  display:block;
  flex:0 0 auto;
  min-width:0;
  line-height:1;
  text-align:center;
  animation:lmv-initial-ink 1.4s .6s cubic-bezier(.22,1,.36,1) both
}

.lmv .lmv-intro-initial:first-child {
  left:auto;
  right:auto;
  top:auto;
  bottom:auto;
  margin:0;
  z-index:2
}

.lmv .lmv-intro-initial:last-child {
  left:auto;
  right:auto;
  top:auto;
  bottom:auto;
  margin:0 0 0 -.16em;
  z-index:1;
  animation-delay:.8s
}

.lmv .lmv-intro-bottom {
  position:absolute;
  left:50%;
  bottom:max(6svh,env(safe-area-inset-bottom,0px) + 24px);
  transform:translateX(-50%);
  width:calc(100% - 64px);
  max-width:330px;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:27px;
  animation:lmv-cinema-rise 1.4s 1s both
}

.lmv .lmv-cover-date {
  display:flex;
  justify-content:center;
  align-items:center;
  flex-wrap:wrap;
  gap:10px;
  color:#ffffffeb;
  font-size:11px;
  line-height:1.8;
  letter-spacing:.14em;
  text-align:center;
  overflow-wrap:anywhere
}

.lmv .lmv-cover-date .lmv-date-separator {
  color:#ffffff80;
  font-size:10px;
  font-weight:400
}

.lmv .lmv-intro-open {
  position:relative;
  width:100%;
  min-height:64px;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid #ffffff9c;
  background:#00000018;
  color:#ffffff;
  padding:18px 18px;
  font-size:10px;
  line-height:1.8;
  text-transform:uppercase;
  letter-spacing:.12em;
  text-align:center;
  overflow:hidden;
  transition:background .3s,border-color .3s
}

.lmv .lmv-intro-open::before {
  content:"";
  position:absolute;
  bottom:0;
  left:0;
  width:100%;
  height:2px;
  background:var(--lmv-accent);
  transform:scaleX(.28);
  transform-origin:center;
  transition:transform .5s
}

.lmv .lmv-intro-open::after {
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(115deg,transparent 36%,#ffffff1a 50%,transparent 64%);
  transform:translateX(-100%);
  pointer-events:none;
  animation:lmv-cinema-shine 5s 2s 2
}

.lmv .lmv-intro-open>span {
  position:relative;
  z-index:1
}

.lmv .lmv-intro-open:hover {
  background:#76172d77;
  border-color:#ffffff
}

.lmv .lmv-intro-open:hover::before {
  transform:scaleX(1)
}

.lmv .lmv-intro-open:focus-visible,.lmv .lmv-intro-languages button:focus-visible {
  outline:2px solid #ffffff;
  outline-offset:5px
}

.lmv .lmv-intro-languages {
  position:absolute;
  z-index:5;
  top:max(25px,env(safe-area-inset-top,0px) + 14px);
  left:50%;
  transform:translateX(-50%);
  display:flex;
  gap:4px
}

.lmv .lmv-intro-languages button {
  min-width:44px;
  min-height:44px;
  background:transparent;
  color:#ffffff;
  border:0;
  border-bottom:1px solid transparent;
