  opacity:.65
}

.lmv .lmv-intro-languages button[aria-pressed="true"] {
  opacity:1;
  border-bottom-color:#ffffffb3
}

.lmv.lmv-intro.is-opening .lmv-cover {
  opacity:0;
  pointer-events:none
}

.lmv.lmv-intro.is-opening .lmv-cover-portrait img {
  animation:none;
  transform:scale(1.2)
}

.lmv.lmv-intro.is-opening .lmv-intro-emblem {
  scale:1.07;
  opacity:0
}

@keyframes lmv-cinema-breathe {
  from {
    transform:scale(1.04)
  }
  to {
    transform:scale(1.12)
  }
}

@keyframes lmv-cinema-rise {
  from {
    opacity:0;
    translate:0 18px
  }
  to {
    opacity:1;
    translate:0 0
  }
}

@keyframes lmv-emblem-ink {
  from {
    opacity:0;
    filter:blur(6px)
  }
  to {
    opacity:1;
    filter:blur(0)
  }
}

@keyframes lmv-initial-ink {
  from {
    opacity:0;
    transform:translateY(12px);
    filter:blur(5px)
  }
  to {
    opacity:1;
    transform:translateY(0);
    filter:blur(0)
  }
}

@keyframes lmv-cinema-shine {
  0%,65%,100% {
    transform:translateX(-110%)
  }
  35% {
    transform:translateX(110%)
  }
}

@media(max-width:350px) {
  .lmv .lmv-cover-aside {
    font-size:8px;
    letter-spacing:.17em
  }
  .lmv .lmv-intro-bottom {
