  }
  .lmv .lmv-cover-aside {
    top:28px
  }
  .lmv .lmv-intro-emblem {
    left:29%;
    top:53%
  }
  .lmv .lmv-intro-bottom {
    left:72%;
    bottom:50%;
    transform:translate(-50%,50%);
    width:39%;
    gap:22px
  }
  .lmv .lmv-intro-languages {
    left:auto;
    right:28px;
    top:14px;
    transform:none
  }
}

@media(prefers-reduced-motion:reduce) {
  .lmv.lmv-intro.is-opening .lmv-cover-portrait img {
    transform:none
  }
  .lmv.lmv-intro.is-opening .lmv-intro-emblem {
    scale:1
  }
  .lmv .lmv-cover-portrait img {
    transform:none
  }
}

.wedding-page:has(> .dnt) {
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0;
  min-height: 100svh;
  background: #f8f4f0;
}
.dnt {
  --dnt-paper: #faf7f4;
  --dnt-ink: #4a3239;
  --dnt-muted: #826f72;
  --dnt-wine: #471327;
  --dnt-wine-light: #622239;
  --dnt-border: #d6c8bf;
  --dnt-serif: "Cormorant Garamond", "Times New Roman", serif;
  --dnt-script: "Monsieur La Doulaise", "Great Vibes", "Cormorant Garamond", Georgia, serif;
  --dnt-sans: "Jost", Arial, sans-serif;
  box-sizing: border-box;
  color: var(--dnt-ink);
  font-family: var(--dnt-sans);
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
.dnt *,
.dnt *::before,
.dnt *::after { box-sizing: border-box; }
.dnt :where(h1, h2, h3, p, figure, fieldset) { margin: 0; }
.dnt :where(a, button, input, textarea) { -webkit-tap-highlight-color: transparent; }
.dnt img { display: block; max-width: 100%; }
.dnt button { font-family: var(--dnt-sans); cursor: pointer; }
.dnt a { color: inherit; }
.dnt :where(button, a, input, textarea):focus-visible {
  outline: 2px solid #9b6478;
  outline-offset: 5px;
}
.dnt button:disabled { cursor: default; }
.dnt-heading {
  font-family: var(--dnt-serif);
  font-size: clamp(37px, 7.9vw, 51px);
  line-height: 1.03;
  font-weight: 400;
  letter-spacing: -0.035em;
  text-wrap: balance;
}
.dnt-kicker {
  font-family: var(--dnt-sans);
  font-size: 9px;
  line-height: 1.6;
  font-weight: 400;
  letter-spacing: 0.21em;
  text-transform: uppercase;
}
.dnt-body {
  font-family: var(--dnt-sans);
  font-size: 13px;
  font-weight: 300;
  line-height: 1.95;
  text-wrap: pretty;
}
.dnt-date {
  font-family: var(--dnt-serif);
  font-size: 18px;
  line-height: 1.4;
  font-weight: 400;
  letter-spacing: 0.03em;
}
.dnt-script-name {
  display: block;
  font-family: var(--dnt-script);
  font-size: clamp(68px, 13vw, 98px);
  line-height: 1.02;
  font-weight: 400;
}
.dnt-ampersand {
  display: block;
  font-family: var(--dnt-serif);
  font-style: italic;
  font-size: 25px;
  line-height: 1;
  color: var(--dnt-muted);
}
.dnt-icon { display: inline-block; flex: 0 0 auto; overflow: visible; }
.dnt-flourish { display: block; width: 190px; height: auto; margin-inline: auto; opacity: 0.7; }
.dnt-flourish-bottom { transform: rotate(180deg); }
.dnt-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 47px;
  min-width: 205px;
  padding: 13px 25px;
  border: 1px solid #b9a49f;
  border-radius: 999px;
  background: transparent;
  color: var(--dnt-ink);
  font-family: var(--dnt-sans);
  font-size: 9px;
  font-weight: 400;
  line-height: 1.5;
  text-transform: uppercase;
  letter-spacing: 0.17em;
  text-decoration: none;
  transition: background 220ms, border-color 220ms, color 220ms, transform 220ms;
}
.dnt-button:not(:disabled):hover { background: #ece3dd; border-color: #a48787; transform: translateY(-2px); }
.dnt-text-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 7px 5px;
  border: 0;
  border-bottom: 1px solid #d5c5bc;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font-family: var(--dnt-sans);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-decoration: none;
}
.dnt-reveal {
  opacity: 0;
  transform: translateY(23px);
  transition: opacity 850ms ease, transform 950ms cubic-bezier(0.2, 0.65, 0.2, 1);
}
.dnt-reveal.dnt-is-visible { opacity: 1; transform: none; }
/* DENTELLE — jedinstven prikaz čipkane trake na svim sekcijama.
   Slika se nikada ne rasteže na fiksnu visinu niti se zumira na 790px.
   Kontrolisano se odseca samo providna margina iznad čipke. */
.dnt {
  --dnt-edge-crop: clamp(21px, calc(6.5vw + 7px), 57px);
  --dnt-edge-height: clamp(92px, 29vw, 180px);
}
.dnt .dnt-lace {
  position: absolute;
  left: 0;
  right: 0;
  width: 100%;
  height: var(--dnt-edge-height);
  display: block;
  overflow: hidden;
  pointer-events: none;
  z-index: 5;
  margin: 0;
  padding: 0;
}
.dnt .dnt-lace-top {
  top: 0;
  bottom: auto;
  transform: none;
}
.dnt .dnt-lace-bottom {
  top: auto;
  bottom: 0;
  transform: scaleY(-1);
  transform-origin: center center;
}
.dnt .dnt-lace > img {
  position: absolute;
  display: block;
  top: calc(-1 * var(--dnt-edge-crop));
  left: 0;
  width: 100%;
  max-width: none;
  min-width: 0;
  height: auto;
  max-height: none;
  object-fit: initial;
  object-position: initial;
  transform: none;
  opacity: 1;
  filter: drop-shadow(0 1px 1px rgba(74, 50, 57, .10));
}

.dnt-pearl {
  display: block;
  position: absolute;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: radial-gradient(circle at 33% 28%, #fffefa 0%, #f7f0e5 37%, #d1bca7 74%, #f9f4e8 100%);
  box-shadow: 1px 2px 4px #947f6540, inset 1px 1px 1px #fff;
}
.dnt[data-script="cyrillic"] { --dnt-script: "Cormorant Garamond", Georgia, serif; }
.dnt[data-script="cyrillic"] .dnt-script-name,
.dnt[data-script="cyrillic"] .dnt-intro-names,
.dnt[data-script="cyrillic"] .dnt-closing-names,
.dnt[data-script="cyrillic"] .dnt-rsvp-signature { font-style: italic; }

/* ============================================================
   DENTELLE INTRO / 4 ORIGINALNA PROVIDNA KRILA
   Jedno WebP krilo = celo transparentno platno 1024x1536.
   Samo aktivni cipkani trougao ima alfa piksele; ne rezemo sliku
   clip-path-om. Sve cetiri slike ostaju savrseno poravnate.
   Sarke su na 4 spoljne ivice platna.
   ============================================================ */
.dnt-intro {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 100svh;
  overflow: hidden;
  background: #efe7e0;
}
.dnt-intro::before {
  content: "";
  position: absolute;
  inset: -20px;
  background: radial-gradient(ellipse, #fcf8f5 8%, #e7d9cf 100%);
  pointer-events: none;
}
.dnt-intro-stage {
  position: relative;
  isolation: isolate;
  width: min(100%, 620px);
  /* Visinu sada diktira isti sadrzaj kao u zavrsnoj kartici. */
  height: auto;
  min-height: min(100svh, 980px);
  max-height: none;
  background: #faf6f2;
  box-shadow: 0 0 65px #795e5420;
  overflow: hidden;
  perspective: 1500px;
  perspective-origin: center center;
}
/* Nevidljiva, ali u layout-u: identicna visina stvarne InvitationCard. */
.dnt-intro .dnt-intro-sizing {
  width: 100%;
  visibility: hidden;
  pointer-events: none;
  user-select: none;
}
.dnt-intro .dnt-intro-card,
.dnt-intro .dnt-four-flaps,
.dnt-intro .dnt-intro-vignette {
  position: absolute;
  inset: 0;
}
/* Ovo je JEDINA pozivnica, ispod krila. */
.dnt-intro .dnt-intro-card {
  z-index: 1;
  background: var(--dnt-paper, #fffaf5);
  overflow: hidden;
  pointer-events: none;
}
.dnt-intro .dnt-intro-frame {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: fill;
  /* Potpuno isti filter kao dnt-hero-frame na sledecoj kartici. */
  filter: saturate(0.7) brightness(1.03);
  pointer-events: none;
  user-select: none;
}
.dnt-intro .dnt-intro-card .dnt-hero-content {
  position: relative;
  z-index: 1;
  height: 100%;
  min-height: 100%;
  padding-top: clamp(82px, 14svh, 142px);
  padding-bottom: clamp(82px, 14svh, 142px);
  opacity: 1;
  transform: none;
  pointer-events: none;
}

.dnt-intro .dnt-four-flaps {
  z-index: 7;
  pointer-events: none;
  transform-style: preserve-3d;
}
/* Providni veo smanjuje citljivost slike ispod dok su krila zatvorena. */
.dnt-intro .dnt-lace-veil {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: rgba(252, 245, 239, .36);
  pointer-events: none;
  transition: opacity 1350ms ease 350ms;
}
.dnt-intro.dnt-is-opening .dnt-lace-veil {
  opacity: 0;
}
/* Sva cetiri istovetna platna potpuno se preklapaju,
   ali stvarni vidljivi delovi su razliciti zahvaljujuci alfa kanalu. */
.dnt-intro .dnt-lace-door {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transform: translateZ(0) rotateX(0deg) rotateY(0deg);
  will-change: transform;
  transition: transform 3000ms cubic-bezier(.65, 0, .35, 1);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.dnt-intro .dnt-lace-door-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: fill;
  pointer-events: none;
  user-select: none;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.dnt-intro .dnt-lace-door--top {
  z-index: 4;
  transform-origin: 50% 0%;
  transition-delay: 0ms;
}
.dnt-intro .dnt-lace-door--right {
  z-index: 3;
  transform-origin: 100% 50%;
  transition-delay: 140ms;
}
.dnt-intro .dnt-lace-door--bottom {
  z-index: 2;
  transform-origin: 50% 100%;
  transition-delay: 250ms;
}
.dnt-intro .dnt-lace-door--left {
  z-index: 3;
  transform-origin: 0% 50%;
  transition-delay: 140ms;
}

/* Kao 4 sarke: otvaraju se ka spoljasnjosti,
   bez translacije i bez dodatne koverte. */
.dnt-intro.dnt-is-opening .dnt-lace-door--top {
  transform: rotateX(-169deg);
}
.dnt-intro.dnt-is-opening .dnt-lace-door--right {
  transform: rotateY(-169deg);
}
.dnt-intro.dnt-is-opening .dnt-lace-door--bottom {
  transform: rotateX(169deg);
}
.dnt-intro.dnt-is-opening .dnt-lace-door--left {
  transform: rotateY(169deg);
}

/* Pecat je sada fizicki vezan za gornje krilo, pa se krece zajedno s njim. */
.dnt-intro .dnt-lace-door-seal {
  position: absolute;
  z-index: 2;
  width: 27.1%;
  left: 50%;
  top: 45.83%;
  object-fit: contain;
  transform: translate(-50%, -50%) scale(.985);
  pointer-events: none;
  user-select: none;
  background: transparent;
  mix-blend-mode: multiply;
  filter: drop-shadow(0 2px 4px rgba(99,75,64,.11)) brightness(.99) contrast(1.02);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

.dnt-intro .dnt-intro-vignette {
  z-index: 8;
  background: linear-gradient(180deg, #faf4ed22, transparent 22%, transparent 71%, #f5eee733);
  pointer-events: none;
  transition: opacity 320ms ease;
}
.dnt-intro .dnt-intro-kicker {
  position: absolute;
  z-index: 9;
  top: max(36px, 6%);
  left: 15px;
  right: 15px;
  margin: 0;
  font-size: 9px;
  font-weight: 400;
  letter-spacing: .3em;
  text-align: center;
  text-transform: uppercase;
  color: #65474c;
  pointer-events: none;
  transition: opacity 320ms ease;
}
.dnt-intro .dnt-intro-caption {
  position: absolute;
  z-index: 9;
  left: 8%;
  right: 8%;
  bottom: max(35px, 7.5%);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  pointer-events: none;
  transition: opacity 320ms ease;
}
.dnt-intro .dnt-intro-names {
  font-family: var(--dnt-script);
  font-size: clamp(34px, 8vw, 47px);
  font-weight: 400;
  line-height: 1.5;
  color: #54343e;
  text-wrap: balance;
}
.dnt-intro .dnt-intro-names span {
  padding-inline: 4px;
  font-family: var(--dnt-serif);
  font-size: .52em;
  font-style: italic;
}
.dnt-intro .dnt-intro-date {
  font-family: var(--dnt-serif);
  font-size: 16px;
  letter-spacing: .035em;
}
.dnt-intro .dnt-open-surface {
  position: absolute;
  z-index: 11;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
}
.dnt-intro .dnt-open-surface:disabled {
  cursor: default;
  pointer-events: none;
}
.dnt-intro .dnt-open-surface:focus-visible {
  outline: 2px solid #967365;
  outline-offset: -5px;
}
.dnt-intro .dnt-wax-seal { display: none; }
.dnt-intro.dnt-is-opening .dnt-intro-caption,
.dnt-intro.dnt-is-opening .dnt-intro-kicker,
.dnt-intro.dnt-is-opening .dnt-intro-vignette { opacity: 0; }
.dnt-intro.dnt-is-opening .dnt-intro-card .dnt-hero-content {
  opacity: 1;
  transform: none;
}
@media (max-height: 580px) {
  .dnt-intro .dnt-intro-kicker { top: 20px; font-size: 8px; }
  .dnt-intro .dnt-intro-caption { bottom: 23px; }
  .dnt-intro .dnt-intro-names { font-size: 32px; line-height: 1.25; }
  .dnt-intro .dnt-intro-card .dnt-hero-content { padding-top: 55px; padding-bottom: 50px; }
  .dnt-intro .dnt-intro-card .dnt-hero-names .dnt-script-name { font-size: 40px; }
  .dnt-intro .dnt-intro-card .dnt-hero-names { margin-block: 15px; }
  .dnt-intro .dnt-intro-card .dnt-hero-villa { width: 155px; margin-block: 15px; }
}
@media (prefers-reduced-motion: reduce) {
  .dnt-reveal { opacity: 1; transform: none; transition: none; }
  .dnt .dnt-button { transition: none; }
  .dnt-intro .dnt-lace-door,
  .dnt-intro .dnt-lace-veil,
  .dnt-intro .dnt-lace-door-seal,
  .dnt-intro .dnt-intro-caption,
  .dnt-intro .dnt-intro-vignette,
  .dnt-intro .dnt-intro-kicker {
    transition-duration: 1ms;
    transition-delay: 0ms;
  }
  .dnt-intro.dnt-is-opening .dnt-intro-card .dnt-hero-content {
    animation-duration: 1ms;
    animation-delay: 0ms;
  }
}

/* Manji inicijali na telefonu */
@media (max-width: 600px) {
  .lmv.lmv-intro .lmv-intro-monogram {
    font-size: calc(var(--lmv-emblem-size) * 0.40);
  }
}


/* ================================================================
   DENTELLE – STARI PRIKAZ ZATVORENOG PISMA
   Samo vidljiva cipkana krila/pecat/tekst zatvorenog pisma.
   Pozadina prave kartice ostaje u originalnoj geometriji, tako
   da nema ponovnog rastezanja okvira posle animacije.
   ================================================================ */
.dnt-intro .dnt-four-flaps,
.dnt-intro .dnt-intro-vignette {
  top: 0;
  bottom: auto;
  height: min(100svh, 1100px);
}

/* Vraćamo originalni centar 3D otvaranja, nezavisno od
   ukupne visine prave pozivnice koja se nalazi ispod. */
.dnt-intro .dnt-intro-stage {
  perspective-origin: 50% min(50svh, 550px);
}

/* Iznad krila kao i ranije. */
.dnt-intro .dnt-intro-kicker {
  top: max(36px, 6svh);
}

/* Imena i datum opet stoje pri dnu VIDLJIVOG pisma,
   a ne pri dnu vise, nevidljive unutrasnje kartice. */
.dnt-intro .dnt-intro-caption {
  bottom: auto;
  top: calc(min(100svh, 1100px) - max(35px, 7.5svh));
  transform: translateY(-100%);
}

@media (max-height: 580px) {
  .dnt-intro .dnt-intro-kicker { top: 20px; }
  .dnt-intro .dnt-intro-caption {
    top: calc(100svh - 23px);
  }
}


/* =========================================
   DENTELLE — PRELAZ SA ČIPKE NA POZIVNICU
   ========================================= */

.wedding-page--dentelle {
  position: relative;
  min-height: 100svh;
  overflow: visible;
}

/* Prava InvitationCard je stalno učitana */
.wedding-page--dentelle .dentelle-card-layer {
  position: relative;
  z-index: 1;
  opacity: 0;
  pointer-events: none;
  transition: opacity 220ms ease;
}

.wedding-page--dentelle .dentelle-card-layer.is-revealed {
  opacity: 1;
}

.wedding-page--dentelle .dentelle-card-layer.is-interactive {
  pointer-events: auto;
}

/* Sadržaj se pojavljuje pred kraj otvaranja */
.wedding-page--dentelle .dentelle-card-layer .dnt-hero-content {
  opacity: 0;
  transition: opacity 220ms ease;
}

.wedding-page--dentelle
  .dentelle-card-layer.is-revealed
  .dnt-hero-content {
  opacity: 1;
  transition-delay: 2800ms;
}

/* Četiri čipkana krila preko prave kartice */
.wedding-page--dentelle > .dnt-intro {
  position: fixed;
  inset: 0;
  z-index: 1000;
  width: 100%;
  height: 100svh;
  min-height: 100svh;
  margin: 0;
  background: transparent;
}

/* Uklanjanje vela prilikom otvaranja */
.wedding-page--dentelle > .dnt-intro::before {
  opacity: 1;
  transition: opacity 280ms ease;
}

.wedding-page--dentelle > .dnt-intro.dnt-is-opening::before {
  opacity: 0;
}

/* Usklađivanje čipke sa unutrašnjom karticom */
.wedding-page--dentelle .dnt-intro-stage {
  width: min(100%, 620px);
  height: min(100svh, 980px);
  min-height: min(100svh, 980px);
  max-height: min(100svh, 980px);
  background: transparent;
  box-shadow: none;
}

.wedding-page--dentelle .dnt-intro .dnt-four-flaps,
.wedding-page--dentelle .dnt-intro .dnt-intro-vignette {
  top: 0;
  bottom: auto;
  height: 100%;
}

/* Pristupačnost */
@media (prefers-reduced-motion: reduce) {
  .wedding-page--dentelle .dentelle-card-layer,
  .wedding-page--dentelle
    .dentelle-card-layer .dnt-hero-content,
  .wedding-page--dentelle > .dnt-intro::before {
    transition: none;
  }
}


.dnt-intro .dnt-lace-door-seal {
  position: absolute;
  z-index: 2;
  width: 27.1%;
  left: 50%;
  top: 45.83%;
  object-fit: contain;

  transform: translate(-50%, -50%) scale(.985);

  opacity: 1;
  mix-blend-mode: normal;

  background-color: #eee1d3;
  border-radius: 50%;

  filter: drop-shadow(0 3px 6px rgba(99, 75, 64, .18));

  pointer-events: none;
  user-select: none;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

.dnt-hero-swans {
  display: block;
  width: 82px;
  max-width: 38%;
  height: auto;
  margin: 0 auto 16px;
  opacity: 1;
}
/* ============================================================
   DENTELLE 2026 — završno usklađivanje introa i glavne kartice
   Isključivo Dentelle: Lumiere stilovi ostaju neizmenjeni.
   Četiri originalna providna krila i dalje se otvaraju na četiri strane.
   ============================================================ */
.wedding-page--dentelle .dentelle-card-layer {
  /* Originalni lace-frame.webp postoji i ISPOD zatvorenih krila.
     Ne prikazujemo drugi, lažni okvir pri završetku animacije. */
  opacity: 1;
  visibility: visible;
  pointer-events: none;
}
.wedding-page--dentelle .dentelle-card-layer.is-interactive {
  pointer-events: auto;
}
.wedding-page--dentelle .dentelle-card-layer .dnt-hero-paper > .dnt-hero-content {
  animation: none;
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 750ms ease, transform 900ms cubic-bezier(.22, 1, .36, 1);
}
.wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-paper > .dnt-hero-content {
  opacity: 1;
  transform: translateY(0);
  transition-delay: 1850ms;
}
.wedding-page--dentelle > .dnt-intro::before {
  /* Raniji puni, neprovidni sloj skrivao je lace-frame pozivnicu. */
  background: transparent;
}
.wedding-page--dentelle .dnt-intro .dnt-intro-stage {
  background: transparent;
}
.wedding-page--dentelle .dnt-intro .dnt-lace-veil {
  background: rgba(252, 246, 240, .26);
}
.wedding-page--dentelle .dnt-intro .dnt-intro-vignette {
  background: linear-gradient(180deg, #fffaf523, transparent 28%, transparent 70%, #f7efe33b);
}
.wedding-page--dentelle .dnt-intro .dnt-lace-door-seal {
  background: transparent;
  filter: drop-shadow(0 3px 7px rgba(74, 43, 49, .22));
}
/* Zadržavamo originalnu površinu za klik, bez dodatnog dugmeta. */
.wedding-page--dentelle .dnt-intro .dnt-open-surface {
  touch-action: manipulation;
}

@media (max-width: 599px) {
  .wedding-page--dentelle .dnt-intro .dnt-lace-veil {
    background: rgba(252, 246, 240, .21);
  }
}
@media (prefers-reduced-motion: reduce) {
  .wedding-page--dentelle .dentelle-card-layer .dnt-hero-paper > .dnt-hero-content,
  .wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-paper > .dnt-hero-content {
    transition-duration: 1ms;
    transition-delay: 0ms;
  }
}


/* ============================================================
   DENTELLE MOBILE MOTION — luksuzni detalji, samo ovaj šablon.
   Transformi se primenjuju samo na decu; NE menjamo geometriju
   četiri čipkana krila, poziciju čipkane trake ili modalni overlay.
   ============================================================ */
@keyframes dnt-m-seal-breathe {
  0%, 100% { transform: translate(-50%, -50%) scale(.985); }
  50% { transform: translate(-50%, -50%) scale(1.027); }
}
@keyframes dnt-m-lace-appear {
  from { opacity: .52; filter: drop-shadow(0 1px 1px rgba(74,50,57,0)); }
  to { opacity: 1; filter: drop-shadow(0 1px 1px rgba(74,50,57,.10)); }
}
@keyframes dnt-m-ink-arrive {
  from { opacity: 0; transform: translate3d(0,15px,0); }
  to { opacity: 1; transform: translate3d(0,0,0); }
}
@keyframes dnt-m-soft-lift {
  from { opacity: 0; transform: translate3d(0,17px,0) scale(.985); }
  to { opacity: 1; transform: translate3d(0,0,0) scale(1); }
}
@keyframes dnt-m-swan-breathe {
  0%, 100% { transform: translate3d(0,0,0); }
  50% { transform: translate3d(0,-5px,0); }
}
@keyframes dnt-m-sheen {
  from { transform: translate3d(-135%,0,0) skewX(-20deg); }
  to { transform: translate3d(240%,0,0) skewX(-20deg); }
}

/* Blago pulsiranje pečata SAMO dok gost ne otvori pozivnicu. */
.wedding-page--dentelle .dnt-intro:not(.dnt-is-opening) .dnt-lace-door-seal {
  animation: dnt-m-seal-breathe 3.4s ease-in-out infinite;
}
.wedding-page--dentelle .dnt-intro.dnt-is-opening .dnt-lace-door-seal {
  animation: none;
}
/* Čipka ostaje vidljiva i bez JS-a — animacija se pokrene jednom. */
.dnt .dnt-lace.dnt-lace-seen > img {
  animation: dnt-m-lace-appear 1.15s ease-out both;
}
/* Imena ulaze kao rukom ispisana, pri KRAJU animacije otvaranja.
   Animira se samo prava kartica, ne duplirana intro kartica. */
.wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-family {
  animation: dnt-m-ink-arrive .85s 2.17s cubic-bezier(.22,1,.36,1) both;
}
.wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-names .dnt-script-name:first-child {
  animation: dnt-m-ink-arrive 1.05s 2.36s cubic-bezier(.22,1,.36,1) both;
}
.wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-names .dnt-ampersand {
  animation: dnt-m-ink-arrive .85s 2.53s cubic-bezier(.22,1,.36,1) both;
}
.wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-names .dnt-script-name:last-child {
  animation: dnt-m-ink-arrive 1.05s 2.69s cubic-bezier(.22,1,.36,1) both;
}
.wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-content > .dnt-date {
  animation: dnt-m-ink-arrive .85s 2.88s cubic-bezier(.22,1,.36,1) both;
}
/* Blaga, slojevita pojava teksta, samo kada je sekcija na ekranu. */
.dnt-reveal.dnt-is-visible > .dnt-kicker {
  animation: dnt-m-ink-arrive .8s .05s both;
}
.dnt-reveal.dnt-is-visible > .dnt-heading,
.dnt-reveal.dnt-is-visible > .dnt-gift-title,
.dnt-reveal.dnt-is-visible > .dnt-closing-text {
  animation: dnt-m-ink-arrive .95s .17s cubic-bezier(.22,1,.36,1) both;
}
.dnt-reveal.dnt-is-visible > .dnt-body,
.dnt-reveal.dnt-is-visible > .dnt-day-note {
  animation: dnt-m-ink-arrive .9s .29s cubic-bezier(.22,1,.36,1) both;
}
.dnt-reveal.dnt-is-visible > .dnt-welcome-swans {
  animation: dnt-m-soft-lift 1s .07s cubic-bezier(.22,1,.36,1) both,
             dnt-m-swan-breathe 6s 1.3s ease-in-out infinite;
}
/* Korisnik dodiruje celu čipku kao i pre; bez novih UI kontrola. */
@media (hover: none) and (pointer: coarse) {
  .dnt .dnt-button,
  .dnt .dnt-text-button { touch-action: manipulation; }
  .dnt .dnt-button:active { transform: scale(.975); }
  .dnt .dnt-text-button:active { opacity: .68; }
}
@media (prefers-reduced-motion: reduce) {
  .wedding-page--dentelle .dnt-intro:not(.dnt-is-opening) .dnt-lace-door-seal,
  .dnt .dnt-lace.dnt-lace-seen > img,
  .wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-family,
  .wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-names .dnt-script-name,
  .wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-names .dnt-ampersand,
  .wedding-page--dentelle .dentelle-card-layer.is-revealed .dnt-hero-content > .dnt-date,
  .dnt-reveal.dnt-is-visible > .dnt-kicker,
  .dnt-reveal.dnt-is-visible > .dnt-heading,
  .dnt-reveal.dnt-is-visible > .dnt-gift-title,
  .dnt-reveal.dnt-is-visible > .dnt-closing-text,
  .dnt-reveal.dnt-is-visible > .dnt-body,
  .dnt-reveal.dnt-is-visible > .dnt-welcome-swans {
    animation: none !important;
    opacity: 1;
    transform: none;
  }
  /* Izuzetak: geometrija gornjeg pečata mora da ostane centrirana. */
  .wedding-page--dentelle .dnt-intro:not(.dnt-is-opening) .dnt-lace-door-seal {
    transform: translate(-50%, -50%) scale(.985);
  }
}


/* DODAJ NA KRAJ postojećeg newintro.css — BIRTHDAY ÉDITION.
   Postojeći prvi @import već sadrži Monsieur La Doulaise, Jost i Cormorant.
   Ne dodaj novi @import na kraj CSS-a i ne briši postojeće stilove. */

.bde {
  --bde-paper: #f5f4f0;
  --bde-ink: #252925;
  --bde-muted: #6a6c63;
  --bde-accent: #74765a;
  --bde-line: #25292529;
  --bde-serif: "Cormorant Garamond", Georgia, serif;
  --bde-sans: "Jost", Arial, sans-serif;
  --bde-script: "Monsieur La Doulaise", "Great Vibes", cursive;
  --bde-name-scale: 1;
  box-sizing: border-box;
  color: var(--bde-ink);
  background: var(--bde-paper);
  font: 400 15px/1.6 var(--bde-sans);
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%;
  text-align: left;
}
.bde *, .bde *::before, .bde *::after { box-sizing: border-box; }
.bde :where(h1, h2, h3, p, figure) { margin: 0; }
.bde :where(h1, h2, h3) { color: inherit; font-weight: 400; }
.bde :where(button, input, output) { font: inherit; color: inherit; }
.bde :where(button, a, input) { -webkit-tap-highlight-color: transparent; }
.bde :where(button, a) { touch-action: manipulation; }
.bde a { color: inherit; text-decoration: none; }
.bde button { cursor: pointer; }
.bde button:disabled { cursor: default; }
.bde :where(button, a, input):focus-visible { outline: 2px solid var(--bde-accent); outline-offset: 5px; }
.bde :where(img) { display: block; width: 100%; max-width: 100%; user-select: none; -webkit-user-drag: none; }
.bde .bde-kicker { font: 400 9px/1.7 var(--bde-sans); letter-spacing: .19em; text-transform: uppercase; }
.bde .bde-arrow { display: block; width: 21px; height: 21px; flex: 0 0 21px; stroke: currentColor; stroke-width: 1.2; stroke-linecap: round; stroke-linejoin: round; }
.bde .bde-script { display: inline-block; position: relative; font-family: var(--bde-script); font-weight: 400; letter-spacing: 0; text-transform: none; line-height: 1.05; }
.bde .bde-script.bde-script-extended { font-family: "Great Vibes", var(--bde-serif); }
.bde .bde-script-ink { display: block; padding: .15em .16em .22em; margin: -.15em -.16em -.22em; overflow-wrap: anywhere; }
.bde .bde-script-underline { position: absolute; width: 90%; height: 22px; bottom: -12px; left: 2%; pointer-events: none; overflow: visible; }
.bde .bde-script-underline path { stroke: currentColor; stroke-width: .9; stroke-linecap: round; }
.bde .bde-letters { display: inline; }
.bde .bde-word { display: inline-block; white-space: nowrap; }
.bde .bde-letter-mask { display: inline-block; overflow: hidden; vertical-align: bottom; padding-top: .12em; margin-top: -.12em; }
.bde .bde-glyph { display: inline-block; }
.bde .bde-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 55px;
  padding: 17px 22px;
  border: 1px solid var(--bde-ink);
  border-radius: 0;
  background: var(--bde-ink);
  color: #faf9f5;
  font: 400 10px/1.6 var(--bde-sans);
  letter-spacing: .16em;
  text-transform: uppercase;
  box-shadow: none;
  transition: background-color .25s ease, color .25s ease;
}
.bde .bde-button:disabled { opacity: .65; }
.bde .bde-text-link { display: inline-flex; align-items: center; gap: 16px; padding: 12px 0; min-height: 46px; border: 0; border-bottom: 1px solid currentColor; background: transparent; font: 400 9px/1.7 var(--bde-sans); letter-spacing: .14em; text-transform: uppercase; }
.bde .bde-text-link .bde-arrow { width: 18px; height: 18px; flex-basis: 18px; }
.bde .bde-reveal { min-width: 0; }
.bde .bde-photo { position: relative; overflow: hidden; background: #e4e3dd; }
.bde .bde-photo-reveal { position: absolute; inset: 0; }
.bde .bde-photo img { position: absolute; top: -15px; left: 0; height: calc(100% + 30px); object-fit: cover; }

.bde.bde-intro { width: 100%; min-height: 100svh; overflow: hidden; background: #eae9e4; }
.bde .bde-cover-sheet { position: relative; isolation: isolate; width: min(100%, 680px); height: 100svh; min-height: 660px; max-height: 1080px; margin: 0 auto; overflow: hidden; background: var(--bde-paper); }
.bde .bde-cover-image, .bde .bde-cover-wash { position: absolute; inset: 0; z-index: -1; pointer-events: none; }
.bde .bde-cover-image img { height: 100%; object-fit: cover; }
.bde .bde-cover-image { bottom: 115px; -webkit-mask-image: linear-gradient(transparent, #000 10% 85%, transparent 100%); mask-image: linear-gradient(transparent, #000 10% 85%, transparent 100%); }
.bde .bde-cover-wash { background: linear-gradient(180deg, #f5f4f0a8 0%, #f5f4f06b 29%, #f5f4f000 49%, #f5f4f000 62%, #f5f4f0a6 83%, #f5f4f0 100%); }
.bde .bde-cover-meta { position: absolute; left: 26px; right: 26px; top: max(24px, env(safe-area-inset-top)); display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-bottom: 13px; border-bottom: 1px solid var(--bde-line); font-size: 8px; letter-spacing: .15em; }
.bde .bde-cover-meta > span:last-child { white-space: nowrap; }
.bde .bde-cover-type { position: relative; padding: clamp(95px, 13svh, 136px) 25px 0; text-align: center; }
.bde .bde-cover-titles { height: clamp(164px, 23svh, 236px); position: relative; display: grid; place-items: center; margin: 8px 0 16px; }
.bde .bde-cover-age { position: absolute; inset: 0; display: grid; place-items: center; font: 400 clamp(170px, 51vw, 282px)/.82 var(--bde-serif); letter-spacing: -.08em; padding-right: .08em; color: #25292520; }
.bde .bde-cover-name { position: relative; max-width: 100%; transform: translateY(18px); font: 400 calc(clamp(98px, 27vw, 151px) * var(--bde-name-scale))/1 var(--bde-script); }
.bde .bde-cover-label { font: 400 12px/1.5 var(--bde-sans); letter-spacing: .26em; }
.bde .bde-cover-bottom { position: absolute; bottom: max(23px, env(safe-area-inset-bottom)); left: 30px; right: 30px; text-align: center; }
.bde .bde-cover-date { font: 500 23px/1.2 var(--bde-serif); letter-spacing: .015em; }
.bde .bde-cover-city { font-size: 8px; letter-spacing: .19em; margin-top: 7px; text-transform: uppercase; }
.bde .bde-cover-button { width: 100%; max-width: 345px; margin-top: 23px; }
.bde .bde-cover-button > span { flex: 1; }
.bde .bde-cover-footnote { display: block; font-size: 7px; letter-spacing: .17em; margin-top: 15px; }

/* Monsieur La Doulaise ne sadrži ćirilične znakove: čitljiv rukopisni serif fallback. */
.bde[data-script="cyrillic"] { --bde-script: "Cormorant Garamond", Georgia, serif; }
.bde[data-script="cyrillic"] .bde-script { font-style: italic; font-size: .76em; }
.bde[data-script="cyrillic"] .bde-cover-name { font-size: calc(clamp(69px, 20vw, 110px) * var(--bde-name-scale)); }
.bde[data-script="cyrillic"] .bde-cover-name .bde-script { font-size: 1em; }

@media (hover: hover) and (pointer: fine) {
  .bde .bde-button:hover:not(:disabled) { background: #444a3d; border-color: #444a3d; }
  .bde .bde-text-link:hover { color: var(--bde-accent); }
}
@media (max-width: 360px) {
  .bde .bde-cover-meta { left: 20px; right: 20px; font-size: 7px; }
  .bde .bde-cover-bottom { left: 23px; right: 23px; }
  .bde .bde-cover-label { font-size: 10px; }
}
@media (max-height: 720px) and (max-width: 700px) {
  .bde .bde-cover-sheet { min-height: 590px; }
  .bde .bde-cover-type { padding-top: 82px; }
  .bde .bde-cover-titles { height: 124px; margin-top: 0; }
  .bde .bde-cover-image { top: 40px; }
  .bde .bde-cover-age { font-size: 177px; }
  .bde .bde-cover-name { font-size: calc(94px * var(--bde-name-scale)); }
  .bde .bde-cover-bottom { bottom: max(15px, env(safe-area-inset-bottom)); }
  .bde .bde-cover-button { min-height: 49px; margin-top: 16px; }
  .bde .bde-cover-date { font-size: 21px; }
}
@media (prefers-reduced-motion: reduce) {
  .bde *, .bde *::before, .bde *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}

/* DODAJ NA KRAJ newintro.css — BIRTHDAY NOIR PARTY.
   Koristi postojeći Google import za Monsieur La Doulaise, Great Vibes,
   Cormorant Garamond i Jost. Ne dodaje se folder sa fontovima. */

.bno {
  --bno-black: #080909;
  --bno-panel: #101212;
  --bno-white: #f5f4f1;
  --bno-silver: #c9cccd;
  --bno-muted: #a5a9aa;
  --bno-line: #e9eded30;
  --bno-serif: "Cormorant Garamond", Georgia, serif;
  --bno-sans: "Jost", Arial, sans-serif;
  --bno-script: "Monsieur La Doulaise", "Great Vibes", cursive;
  --bno-name-scale: 1;
  position: relative;
  box-sizing: border-box;
  background: var(--bno-black);
  color: var(--bno-white);
  font: 400 15px/1.6 var(--bno-sans);
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%;
  text-align: left;
}
.bno *, .bno *::before, .bno *::after { box-sizing: border-box; }
.bno :where(h1, h2, h3, p, figure) { margin: 0; }
.bno :where(h1, h2, h3) { font-weight: 400; color: inherit; }
.bno :where(button, input, output) { font: inherit; color: inherit; }
.bno a { color: inherit; text-decoration: none; }
.bno :where(button, a, input) { -webkit-tap-highlight-color: transparent; }
.bno :where(button, a) { touch-action: manipulation; }
.bno button { cursor: pointer; }
.bno button:disabled { cursor: default; }
.bno :where(button, a, input):focus-visible { outline: 2px solid #d9dddd; outline-offset: 5px; }
.bno img { display: block; width: 100%; max-width: 100%; user-select: none; -webkit-user-drag: none; filter: grayscale(1); }
.bno .bno-kicker { font: 400 9px/1.8 var(--bno-sans); letter-spacing: .21em; text-transform: uppercase; color: var(--bno-silver); }
.bno .bno-script { display: inline-block; position: relative; font-family: var(--bno-script); font-weight: 400; text-transform: none; letter-spacing: 0; line-height: 1.1; }
.bno .bno-script.bno-script-extended { font-family: "Great Vibes", var(--bno-serif); }
.bno .bno-ink { display: block; padding: .15em .18em .25em; margin: -.15em -.18em -.25em; overflow-wrap: anywhere; }
.bno .bno-handline { position: absolute; bottom: -15px; left: 2%; width: 94%; height: 25px; overflow: visible; pointer-events: none; }
.bno .bno-handline path { stroke: var(--bno-silver); stroke-width: .8; stroke-linecap: round; }
.bno .bno-word { display: inline-block; white-space: nowrap; }
.bno .bno-letter-mask { display: inline-block; overflow: hidden; vertical-align: bottom; padding: .14em .025em 0; margin: -.14em -.025em 0; }
.bno .bno-glyph { display: inline-block; transform-origin: 0 100%; }
