.bsl h1, .bsl h2, .bsl h3, .bsl p { margin: 0; font-weight: 400; }
.bsl img { display: block; height: auto; max-width: 100%; user-select: none; -webkit-user-drag: none; }
.bsl a { color: inherit; text-decoration: none; }
.bsl button, .bsl input, .bsl textarea { font-family: var(--bsl-sans); }
.bsl button { cursor: pointer; -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
.bsl button:disabled { cursor: default; }
.bsl button:focus-visible, .bsl a:focus-visible { outline: 2px solid currentColor; outline-offset: 5px; }
.bsl .bsl-icon { width: 24px; height: 24px; flex: 0 0 24px; object-fit: contain; }
.bsl .bsl-script {
  display: inline-block;
  max-width: 100%;
  font-family: var(--bsl-script);
  font-weight: 400;
  font-style: normal;
  font-synthesis: none;
  line-height: 1.05;
  letter-spacing: 0;
  text-transform: none;
}
.bsl-writing > span {
  display: block;
  padding: .16em .26em .22em;
  margin: -.16em -.26em -.22em;
  clip-path: inset(-2% -2% -2% -2%);
  transition: clip-path 1.55s var(--bsl-ease) var(--bsl-delay, 0s);
}
.bsl-reveal {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition: opacity .85s ease var(--bsl-delay, 0s), transform 1.1s var(--bsl-ease) var(--bsl-delay, 0s);
}
.bsl-word { display: inline-block; white-space: nowrap; }
.bsl-letter-window { display: inline-block; overflow: hidden; vertical-align: bottom; padding-bottom: .04em; margin-bottom: -.04em; }
.bsl-glyph {
  display: inline-block;
  transform: translate3d(0, 0, 0) rotate(0deg);
  opacity: 1;
  transition: transform .85s var(--bsl-ease) var(--bsl-delay, 0s), opacity .55s ease var(--bsl-delay, 0s);
}
.bsl-motion-ready .bsl-reveal:not(.bsl-visible) { opacity: 0; transform: translate3d(0, 24px, 0); }
.bsl-motion-ready .bsl-writing:not(.bsl-visible) > span { clip-path: inset(-2% 103% -2% -2%); }
.bsl-motion-ready .bsl-letters:not(.bsl-visible) .bsl-glyph { transform: translate3d(0, 110%, 0) rotate(4deg); opacity: 0; }
.bsl .bsl-eyebrow { font-size: 9px; font-weight: 500; letter-spacing: .19em; line-height: 1.8; text-transform: uppercase; }
.bsl .bsl-button {
  appearance: none;
