@keyframes bsl-twinkle { 0%, 100% { opacity: .2; transform: scale(.65) rotate(0); } 45% { opacity: .95; transform: scale(1.1) rotate(16deg); } 65% { opacity: .25; transform: scale(.75) rotate(0); } }
