.bsa{--bsa-ink:#1a1a19;--bsa-paper:#fff;--bsa-line:rgba(26,26,25,.2);--bsa-name-scale:1;box-sizing:border-box;color:var(--bsa-ink);font-family:Arial,Helvetica,sans-serif;font-weight:400;font-size:14px;line-height:1.75;-webkit-font-smoothing:antialiased;text-align:center;color-scheme:light}
.bsa *,.bsa *::before,.bsa *::after{box-sizing:border-box}
.bsa h1,.bsa h2,.bsa h3,.bsa p,.bsa figure{margin:0}
.bsa button,.bsa input,.bsa textarea,.bsa select{font:inherit;letter-spacing:inherit}
.bsa button{cursor:pointer;-webkit-tap-highlight-color:transparent}
.bsa button:disabled{cursor:default}
.bsa a{color:inherit;text-decoration:none}
.bsa img{display:block;max-width:100%}
.bsa button:focus-visible,.bsa a:focus-visible,.bsa input:focus-visible{outline:2px solid currentColor;outline-offset:5px}
.bsa-script{display:inline-block;position:relative;font-family:"BSA Script","BSA Serif",Georgia,serif;font-size:1.5em;font-weight:400;line-height:1.35;letter-spacing:0;padding:.08em .16em .13em}
.bsa[data-script="cyrillic"] .bsa-script{font-family:"BSA Serif",Georgia,serif;font-style:italic;font-size:1em}
.bsa-letters{display:block;overflow:visible}
.bsa-word{display:inline-block;white-space:nowrap;overflow:visible}
.bsa-letter{display:inline-block;overflow:visible}
.bsa-icon{display:block;width:46px;height:46px;margin-inline:auto;object-fit:contain;flex-shrink:0}
.bsa-arrow{display:block;width:25px;height:18px;margin:0;object-fit:contain;transition:transform .25s ease}
.bsa-button{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:20px;min-height:52px;max-width:100%;padding:13px 25px;border:1px solid var(--bsa-ink);border-radius:999px;background:transparent;color:var(--bsa-ink);font-family:Arial,Helvetica,sans-serif;font-size:12px;font-weight:400;line-height:1.4;text-align:center;text-decoration:none;box-shadow:none;transition:background .25s ease,color .25s ease,box-shadow .25s ease;touch-action:manipulation}
.bsa-button span{min-width:0}
.bsa-button:disabled{opacity:.65}
.bsa-button-light,.bsa a.bsa-button-light{background:#fff;color:#191919;border-color:#fff}
.bsa-kicker{font-size:9px;line-height:1.65;letter-spacing:.19em;text-transform:uppercase}
.bsa-bow{pointer-events:none;transform-origin:55% 28%;overflow:visible}
.bsa-bow img{display:block;width:100%;height:auto;max-width:none}
.bsa-intro{position:relative;isolation:isolate;width:100%;min-height:100svh;background:#fff;padding:0}
.bsa-cover{position:relative;isolation:isolate;width:100%;max-width:520px;min-height:740px;height:100svh;margin:0 auto;overflow:hidden;background:#fff;background-image:linear-gradient(137deg,transparent 0 48%,rgba(226,226,223,.2) 49%,rgba(255,255,255,.65) 55%,transparent 60%),linear-gradient(38deg,transparent 14%,rgba(230,230,227,.22) 20%,#fff 27%,transparent 42%);}
.bsa-cover::before{content:"";position:absolute;z-index:-1;inset:0;pointer-events:none;background:linear-gradient(145deg,transparent 47%,rgba(215,215,211,.13) 51%,transparent 57%),linear-gradient(26deg,transparent 29%,rgba(233,233,230,.25) 30%,transparent 39%)}
.bsa-cover-age{position:absolute;z-index:0;left:1%;top:20%;width:96%;font-family:"BSA Serif",Georgia,serif;font-size:clamp(260px,92vw,450px);font-weight:300;font-style:italic;line-height:1.05;letter-spacing:-.1em;color:#dededb;pointer-events:none;text-align:left;user-select:none}
.bsa-cover-age-long{font-size:clamp(230px,72vw,360px);letter-spacing:-.07em;top:24%}
.bsa-cover-bow{position:absolute;z-index:1;width:66%;max-width:350px;top:5%;right:-8%;}
.bsa-cover-kicker{position:absolute;top:max(29px,env(safe-area-inset-top));left:8%;right:8%;font-size:8px;letter-spacing:.25em;text-align:left;line-height:1.5}
.bsa-cover-name{position:absolute;z-index:2;left:4%;right:4%;top:39%;font-family:"BSA Script","BSA Serif",Georgia,serif;font-size:calc(clamp(82px,28vw,142px) * var(--bsa-name-scale));font-weight:400;line-height:1.3;text-align:left;overflow:visible;overflow-wrap:anywhere}
.bsa-cover-name .bsa-script{font-size:1.32em;max-width:100%;padding-block:.07em .19em}
.bsa-cover-copy{position:absolute;z-index:2;top:65%;left:8%;right:8%;text-align:left}
.bsa-cover-invitation{font-family:"BSA Serif",Georgia,serif;font-style:italic;font-size:21px;line-height:1.35;max-width:22ch;text-wrap:balance}
.bsa-cover-date{font-family:"BSA Serif",Georgia,serif;font-style:italic;font-size:19px;line-height:1.6;margin-top:4px!important}
.bsa-enter-wrap{position:absolute;z-index:3;left:8%;right:8%;bottom:max(70px,calc(env(safe-area-inset-bottom) + 50px));text-align:center}
.bsa-enter{width:min(100%,270px);background:rgba(255,255,255,.85);font-size:13px;letter-spacing:.025em;min-height:54px;padding:15px 27px}
.bsa-cover-footnote{position:absolute;left:8%;right:8%;bottom:max(28px,calc(env(safe-area-inset-bottom) + 20px));font-size:9px;letter-spacing:.04em;line-height:1.6;color:#686866}
@media(hover:hover){.bsa-button:hover{box-shadow:0 7px 22px rgba(0,0,0,.08)}.bsa-button:hover .bsa-arrow{transform:translateX(4px)}}
@media(min-width:600px){.bsa-intro{background:#eeedeb;display:grid;place-items:center}.bsa-cover{height:min(940px,100svh);box-shadow:0 0 100px rgba(0,0,0,.045)}.bsa-cover-age{font-size:450px}.bsa-cover-name{font-size:calc(142px * var(--bsa-name-scale))}.bsa-cover-copy{top:67%}}
@media(max-width:360px){.bsa-cover{min-height:660px}.bsa-cover-age{top:21%}.bsa-cover-bow{top:8%;width:67%}.bsa-cover-name{top:40%}.bsa-cover-invitation{font-size:19px}.bsa-cover-date{font-size:18px}.bsa-enter-wrap{bottom:65px}}
@media(prefers-reduced-motion:reduce){.bsa *,.bsa *::before,.bsa *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

