.nwt .nwt-intro-studio { width:100%; display:flex; flex-direction:column; align-items:center; }
.nwt .nwt-intro-overline { margin-bottom:25px; text-align:center; font:400 8px/1.7 var(--nwt-sans); text-transform:uppercase; letter-spacing:.18em; }
