  position: relative;
}

.bb.bb-intro-wrap .bb-intro-copy,
.bb.bb-intro-wrap .efi-andjela-open-hint {
  display: none;
}

.bb.bb-intro-wrap .efi-overlay {
  --efi-flap-duration: 2.4s;
  --efi-bottom-duration: 0s;
  --efi-bottom-delay: 0s;
}

