.nwt { --nwt-paper:#fff; --nwt-ink:#111; --nwt-muted:#646464; --nwt-line:#c8c8cc; --nwt-page-pad:22px; --nwt-display:"NewlywedTimesDisplay",Georgia,serif; --nwt-serif:"NewlywedTimesSerif",Georgia,serif; --nwt-sans:"NewlywedTimesSans",Arial,sans-serif; --nwt-script:"NewlywedTimesScript",cursive; position:relative; isolation:isolate; box-sizing:border-box; color:var(--nwt-ink); font:400 17px/1.6 var(--nwt-serif); -webkit-font-smoothing:antialiased; -webkit-tap-highlight-color:transparent; }
