.nwt .nwt-word-ink { max-width:100%; overflow-wrap:anywhere; }
.nwt .nwt-button { display:inline-flex; justify-content:space-between; align-items:center; gap:20px; min-height:50px; max-width:100%; padding:13px 17px; background:#fff; border:1px solid #111; border-radius:0; color:#111; box-shadow:none; font:400 10px/1.5 var(--nwt-sans); letter-spacing:.055em; text-align:center; transition:background .22s,color .22s,transform .22s; }
