@media(max-width:350px) { .nwt { --nwt-page-pad:18px; } }
@media(max-height:650px) { .nwt.nwt-intro { gap:18px; padding-block:15px; } .nwt .nwt-intro-overline { margin-bottom:14px; } .nwt .nwt-intro-stage { height:60svh; } }
@media(prefers-reduced-motion:reduce) { .nwt *, .nwt *::before,.nwt *::after { transition-duration:.01ms !important; scroll-behavior:auto !important; } }

.nwt .nwt-stack-back,.nwt .nwt-stack-middle { transform:none; }
.nwt .nwt-intro-button { letter-spacing:.055em; }
.nwt .nwt-intro-names { font-size:calc(clamp(30px,9vw,39px)*var(--nwt-intro-name-scale,1)); }
.nwt .nwt-intro-names > span { white-space:nowrap; }



/* NEWLYWED TIMES — veći intro. Dodati na kraj postojećeg newintro.css. */
.nwt.nwt-intro {
  display:grid;
  grid-template-columns:minmax(0,1fr);
  grid-template-rows:minmax(0,1fr) auto;
  justify-items:center;
  align-items:center;
  align-content:stretch;
  height:100svh;
  min-height:0;
  bottom:auto;
  gap:14px;
  padding:max(14px,env(safe-area-inset-top)) 16px max(16px,env(safe-area-inset-bottom));
}
.nwt .nwt-intro-backdrop { background:#fff; }
.nwt .nwt-intro-studio { width:min(100%,480px); height:100%; min-height:0; }
.nwt .nwt-intro-overline { display:none; }
.nwt .nwt-intro-stage { width:100%; height:100%; min-height:0; }
.nwt .nwt-intro-print { padding:clamp(12px,3.5vw,18px); }
.nwt .nwt-intro-edition {
  align-items:center;
  gap:10px;
  padding-bottom:8px;
  font-size:clamp(6.5px,1.85vw,8px);
  letter-spacing:.035em;
}
.nwt .nwt-intro-edition-label { display:flex; align-items:center; gap:8px; min-width:0; }
.nwt .nwt-intro-edition-label > b {
  display:grid;
  flex:0 0 19px;
  place-items:center;
  width:19px;
  height:19px;
  background:#111;
  color:#fff;
  font:400 7px/1 var(--nwt-sans);
  letter-spacing:0;
}
.nwt .nwt-intro-edition > span:last-child { flex:0 0 auto; }
.nwt .nwt-intro-masthead { margin-top:8px; font-size:clamp(23px,8vw,39px); }
.nwt .nwt-intro-deck { margin:8px 0 10px; font-size:13px; }
.nwt .nwt-intro-names { bottom:22px; font-size:calc(clamp(34px,12.4vw,55px)*var(--nwt-intro-name-scale,1)); }
.nwt .nwt-intro-names > i { margin:7px 0; font-size:22px; }
.nwt .nwt-intro-foot { padding-top:9px; font-size:7px; }
.nwt .nwt-intro-button { width:min(100%,480px); min-width:0; min-height:52px; padding-inline:22px; }
@media(min-width:600px) {
  .nwt.nwt-intro { grid-template-rows:min(78svh,740px) auto; align-content:center; }
}
@media(max-height:650px) {
  .nwt.nwt-intro {
    grid-template-rows:minmax(0,1fr) auto;
    align-content:stretch;
    gap:12px;
    padding:max(12px,env(safe-area-inset-top)) 16px max(12px,env(safe-area-inset-bottom));
  }
  .nwt .nwt-intro-stage { height:100%; }
  .nwt .nwt-intro-print { padding:10px; }
  .nwt .nwt-intro-edition { padding-bottom:5px; font-size:6.5px; }
  .nwt .nwt-intro-edition-label > b { width:16px; height:16px; flex-basis:16px; font-size:6px; }
  .nwt .nwt-intro-masthead { margin-top:6px; font-size:clamp(22px,7.4vw,32px); }
  .nwt .nwt-intro-deck { margin:6px 0 8px; padding-block:5px; font-size:11px; }
  .nwt .nwt-intro-names { bottom:12px; font-size:calc(clamp(28px,9vw,38px)*var(--nwt-intro-name-scale,1)); }
  .nwt .nwt-intro-names > i { margin:4px 0; font-size:18px; }
  .nwt .nwt-intro-foot { padding-top:6px; font-size:6px; }
  .nwt .nwt-intro-button { min-height:48px; }
}
